const API = '';
const state = { token: localStorage.getItem('ihbas_token') || '', user: null, page: 'overview', sidebarOpen: false, sidebarCollapsed: localStorage.getItem('ihbas_sidebar_collapsed') === '1', cache: {} };
const $ = (s, root=document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = v => v == null || v === '' ? '—' : (typeof v === 'number' ? v.toLocaleString('en-IN') : String(v));
const dateFmt = v => v ? new Date(v).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}) : '—';
const money = v => '₹' + Number(v || 0).toLocaleString('en-IN',{maximumFractionDigits:2});

async function api(path, options={}) {
  const headers = { ...(options.headers || {}) };
  if (state.token) headers.Authorization = `Bearer ${state.token}`;
  if (options.body && !(options.body instanceof FormData)) headers['Content-Type'] = 'application/json';
  const response = await fetch(API + path, {...options, headers});
  if (response.status === 401 && !path.includes('/auth/login')) { logout(false); throw new Error('Session expired. Please log in again.'); }
  if (!response.ok) {
    let message = `Request failed (${response.status})`;
    try { const data = await response.json(); message = data.message || data.error || message; } catch (_) { try { message = await response.text() || message; } catch (_) {} }
    throw new Error(message);
  }
  if (response.headers.get('content-type')?.includes('text/csv')) {
    const blob = await response.blob(); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href=url; a.download=(response.headers.get('content-disposition')?.match(/filename=([^;]+)/)?.[1] || 'report.csv').replaceAll('"',''); a.click(); URL.revokeObjectURL(url); return {downloaded:true};
  }
  if (response.status === 204) return null;
  return response.json();
}
function toast(message, type='success') {
  const root=$('#toast-root'); if(!root) return; const el=document.createElement('div'); el.className=`toast ${type}`; el.textContent=message; root.append(el); setTimeout(()=>el.remove(),3800);
}
function showLogin() {
  state.token=''; state.user=null; localStorage.removeItem('ihbas_token'); localStorage.removeItem('ihbas_user');
  $('#app').innerHTML=`<div class="login-shell"><section class="login-aside"><div><div class="side-brand" style="border:0;padding:0"><div class="brand-mark">IH</div><div><strong>IHBAS</strong><small>Hospital Operations Platform</small></div></div><div class="eyebrow" style="margin-top:70px">Intelligent Hospital Bed Allocation System</div><h1>Every bed matters.<br>Every minute counts.</h1><p>A single operational workspace for patient admissions, intelligent bed allocation, hospital capacity and care transitions.</p></div><div class="login-foot">Secure role-based access · Academic demonstration system</div></section><section class="login-panel"><div class="login-card"><div class="brand-mark">IH</div><h2>Welcome back</h2><p class="sub">Sign in to continue to your hospital workspace.</p><form id="login-form"><div class="field"><label>PATIENT USER ID / USERNAME / EMAIL</label><input name="identifier" autocomplete="username" required placeholder="Enter Patient User ID, username or email"></div><div class="field"><label>PASSWORD</label><input name="password" type="password" autocomplete="current-password" required placeholder="Enter password"></div><button class="btn block" type="submit">Sign in <span>→</span></button></form><div style="display:flex;justify-content:flex-end;gap:12px;margin-top:14px"><button class="link-btn" data-action="forgot">Forgot password?</button></div><p class="auth-note">Access is controlled by your assigned role. Patient login credentials are issued by the receptionist during hospital registration. Sign in using your Patient User ID or Patient Login ID.</p></div></section></div>`;
  $('#login-form').addEventListener('submit', login);
}
async function login(e) {
  e.preventDefault(); const form=new FormData(e.currentTarget); const button=e.currentTarget.querySelector('button'); button.disabled=true; button.textContent='Signing in…';
  try { const result=await api('/api/auth/login',{method:'POST',body:JSON.stringify({identifier:form.get('identifier'),password:form.get('password')})}); state.token=result.accessToken;state.user=result.user;localStorage.setItem('ihbas_token',state.token);localStorage.setItem('ihbas_user',JSON.stringify(state.user));state.page='overview';renderShell();toast(`Signed in as ${result.user.role}.`); }
  catch(err){toast(err.message,'error');button.disabled=false;button.innerHTML='Sign in <span>→</span>';}
}
function logout(callApi=true) { if(callApi && state.token) api('/api/auth/logout',{method:'POST'}).catch(()=>{}); state.token='';state.user=null;localStorage.removeItem('ihbas_token');localStorage.removeItem('ihbas_user');showLogin(); }
function roleKey(){return state.user?.role || 'PATIENT';}
const navs = {
 ADMIN:[['overview','⌂','Overview','COMMAND'],['wards','▦','Wards & Beds'],['staff','♙','Staff Management'],['patients','♧','Patients'],['allocations','▣','Allocation Monitor'],['admin-waiting','◷','Waiting List'],['reports','▥','Reports & Analytics'],['audit','◷','Audit Logs'],['notifications','♢','Notifications'],['settings','⚙','Settings']],
 RECEPTIONIST:[['overview','⌂','Overview','OPERATIONS'],['patients','♧','Search Patients','OPERATIONS'],['register','＋','Register Patient'],['queue','☷','Admission Queue'],['beds','▦','Bed Availability'],['active','▣','Active Admissions'],['waiting','◷','Waiting List'],['billing','₹','Billing'],['notifications','♢','Notifications']],
 PATIENT:[['overview','⌂','Overview','MY CARE'],['request','＋','Request Admission'],['admission','▣','My Admission'],['history','◷','History'],['bills','₹','Bills'],['availability','▦','Bed Availability'],['notifications','♢','Notifications'],['profile','♙','My Profile']]
};
const titles={overview:'Overview',wards:'Wards & Beds',staff:'Staff Management',patients:'Patients',allocations:'Allocation Monitor','admin-waiting':'Waiting List',reports:'Reports & Analytics',audit:'Audit Logs',notifications:'Notifications',settings:'Settings',register:'Register Patient',patients:'Search Patients',queue:'Admission Queue',beds:'Bed Availability',active:'Active Admissions',waiting:'Waiting List',billing:'Billing',request:'Request Admission',admission:'My Admission',history:'Admission History',bills:'My Bills',availability:'Bed Availability',profile:'My Profile'};
function renderShell(){
 const role=roleKey(), user=state.user||{}; const items=navs[role]||navs.PATIENT;
 $('#app').innerHTML=`<div class="app-shell ${state.sidebarCollapsed?'sidebar-collapsed':''}"><aside class="sidebar ${state.sidebarOpen?'open':''}" id="sidebar"><div class="side-brand"><div class="brand-mark">IH</div><div><strong>IHBAS</strong><small>Hospital Operations</small></div></div><div class="side-section">Workspace</div><nav class="nav-list">${items.map(([id,icon,label,section],i)=>`${section&&i>0?`<div class="side-section">${section}</div>`:''}<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}</nav><div class="side-bottom"><div class="user-chip"><div class="avatar">${esc((user.fullName||user.username||'U').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div style="min-width:0"><strong>${esc(user.fullName||user.username)}</strong><small>${esc(role)} · Active session</small></div></div><button class="nav-item" data-action="logout"><span class="nav-icon">↪</span>Sign out</button></div></aside><div class="mobile-backdrop ${state.sidebarOpen?'show':''}" data-action="close-menu"></div><main class="main"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><button class="icon-btn desktop-sidebar-toggle" data-action="toggle-sidebar" aria-label="Toggle sidebar" title="Collapse or expand sidebar">☰</button><div><div class="crumb">IHBAS / ${esc(titles[state.page]||'Overview')}</div><h2>${esc(titles[state.page]||'Overview')}</h2></div></div><div class="top-actions"><button class="icon-btn" title="Notifications" data-page="notifications">♢<i class="dot"></i></button><div class="who" style="font-size:11px;color:var(--muted)">Today · ${new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}</div></div></header><section class="content" id="content"><div class="empty">Loading workspace…</div></section></main></div>`;
  renderPage().catch(e=>{const target=$('#content');if(target)target.innerHTML=`<section class="panel"><h3>Could not load this page</h3><p class="muted">${esc(e.message)}</p><button class="btn secondary" data-action="refresh-page">Retry</button></section>`;toast(e.message,'error');});
}
function kpi(label,value,icon,foot='Live hospital data'){return `<article class="kpi"><span class="kpi-icon">${icon}</span><div class="kpi-label">${esc(label)}</div><div class="kpi-value">${fmt(value)}</div><div class="kpi-foot">${esc(foot)}</div></article>`;}
function panel(title,body,subtitle=''){return `<section class="panel"><div class="panel-head"><div><h3>${esc(title)}</h3>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div></div>${body}</section>`;}
function table(rows,cols,actions=''){
 if(!rows?.length)return `<div class="empty"><strong>No records found</strong>Records will appear here when data is available.</div>`;
 return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}${actions?'<th>Actions</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c.render?c.render(r):esc(fmt(r[c.key]))}</td>`).join('')}${actions?`<td>${actions(r)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;
}
function statusTag(value){const s=String(value||'').toUpperCase();let cls=['AVAILABLE','ACTIVE','ALLOCATED','SUCCESS','PAID','VERIFIED'].includes(s)?'ok':['WAITING','PENDING','PENDING_VERIFICATION','RESERVED','PARTIALLY_PAID'].includes(s)?'warn':['OCCUPIED','REJECTED','FAILED','DISABLED','DECEASED'].includes(s)?'danger':'info';return `<span class="tag ${cls}">${esc(s.replaceAll('_',' '))}</span>`;}
function bars(rows,labelKey,valueKey){const max=Math.max(1,...rows.map(x=>Number(x[valueKey]||0)));return `<div class="bar-list">${rows.map(x=>`<div class="bar-row"><div class="bar-label" title="${esc(x[labelKey])}">${esc(x[labelKey])}</div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,Number(x[valueKey]||0)/max*100))}%"></div></div><div class="bar-val">${fmt(x[valueKey])}</div></div>`).join('')||'<div class="empty">No chart data.</div>'}</div>`;}
async function renderPage(){
 const c=$('#content'); if(!c)return;c.innerHTML='<div class="empty">Loading…</div>';
 const role=roleKey();
 if(role==='ADMIN') return renderAdmin(c);
 if(role==='RECEPTIONIST') return renderReception(c);
 return renderPatient(c);
}
async function renderAdmin(c){
 const p=state.page;
 if(p==='overview'){
  const statsResult=await api('/api/admin/stats').then(value=>({ok:true,value})).catch(error=>({ok:false,error}));
  if(!statsResult.ok){c.innerHTML=`<section class="panel"><h3>Admin overview could not load</h3><p class="muted">${esc(statsResult.error.message)}</p><p class="muted">The API failed before dashboard data was rendered. Check the backend log for the SQL/API error.</p><button class="btn secondary" data-action="refresh-page">Retry overview</button></section>`;return;}
  const d=statsResult.value;
  const bedResult=await api('/api/bed-board').then(value=>({ok:true,value})).catch(error=>({ok:false,error}));
  const bedMap=bedResult.ok?bedResult.value:[];
  const wardGroups=[...new Set(bedMap.map(b=>b.ward_name))];
  const mapHtml=wardGroups.map(w=>`<div style="margin:14px 0"><div style="font-size:11px;font-weight:800;margin-bottom:8px">${esc(w)}</div><div class="bed-grid">${bedMap.filter(b=>b.ward_name===w).map(b=>`<div class="bed-tile ${String(b.status).toLowerCase()}" title="${esc(b.patient_name||'Unassigned')} · ${esc(b.status)} · ${esc(b.admit_time||'')}"><strong>${esc(b.bed_code)}</strong><small>${esc(b.status.replaceAll('_',' '))}${b.patient_name?` · ${esc(b.patient_name)}`:''}</small></div>`).join('')}</div></div>`).join('');
  c.innerHTML=`<div class="welcome"><div><div class="eyebrow">Hospital command centre</div><h1>Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, ${esc((state.user.fullName||'Admin').split(' ')[0])}</h1><p>Monitor capacity, admissions and hospital operations from one place.</p></div><button class="btn" data-page="wards">＋ Manage wards & beds</button></div><div class="grid kpis">${kpi('Total beds',d.totalBeds,'▦')}${kpi('Available beds',d.availableBeds,'✓')}${kpi('Occupied beds',d.occupiedBeds,'▣')}${kpi('Occupancy rate',`${d.occupancyRate}%`,'◒')}${kpi('Active patients',d.totalPatients,'♧')}${kpi('Active admissions',d.activeAdmissions,'⌂')}${kpi('Pending requests',d.pendingRequests,'☷')}${kpi('ICU beds free',d.icuFreeBeds,'✚')}</div><div class="grid two-col">${panel('Ward occupancy',bars(d.wards.map(x=>({...x,occupancy:x.total_beds?Math.round(x.occupied_beds/x.total_beds*100):0})),'ward_name','occupancy'),'Occupied beds by ward')}${panel('7-day admission trend',bars(d.admissionTrend,'day','admissions'),'Admissions per day')}${panel('Bed status split',bars(d.bedStatus,'status','count'))}${panel('Operational alerts',d.alerts.length?`<div class="alert-list">${d.alerts.map(a=>`<div class="alert"><span>⚠</span><div><b>${esc(a.title)}</b><small>${esc(a.message)}</small></div></div>`).join('')}</div>`:'<div class="empty"><strong>No critical alerts</strong>Current capacity is within configured thresholds.</div>','90% ward occupancy · ICU under 2 free beds')}</div><div style="margin-top:17px">${panel('Live bed map',bedResult.ok?mapHtml:`<div class="empty"><strong>Bed map unavailable</strong>${esc(bedResult.error.message)}. Other overview metrics are still available.</div>`,'Colour-coded hospital bed status. Hover a bed to view current assignment details.')}</div><div style="margin-top:17px">${panel('Ward snapshot',table(d.wards,[{key:'ward_name',label:'Ward'},{key:'ward_type',label:'Type'},{key:'total_beds',label:'Total'},{key:'available_beds',label:'Available'},{key:'occupied_beds',label:'Occupied'},{key:'reserved_beds',label:'Reserved'}]))}</div>`;return;
 }
 if(p==='wards'){
  const [wards,beds]=await Promise.all([api('/api/admin/wards'),api('/api/admin/beds')]);state.cache.wards=wards;state.cache.beds=beds;
  c.innerHTML=`<div class="section-title"><div><h3>Ward and bed inventory</h3><p>Manage ward capacity, bed facilities and operational status.</p></div><div class="toolbar"><button class="btn secondary" data-action="add-ward">＋ Add ward</button><button class="btn" data-action="add-bed">＋ Add bed</button></div></div><div class="grid two-col"><div>${panel('Wards',table(wards,[{key:'ward_name',label:'Ward'},{key:'ward_type',label:'Type'},{key:'capacity',label:'Capacity'},{key:'total_beds',label:'Beds'},{key:'available_beds',label:'Available'},{key:'status',label:'Status',render:r=>statusTag(r.status)}],r=>`<div class="table-actions"><button class="btn small ghost" data-action="edit-ward" data-id="${r.ward_id}">Edit</button><button class="btn small danger" data-action="deactivate-ward" data-id="${r.ward_id}">Disable</button></div>`))}</div><div>${panel('Bed status',bars(['AVAILABLE','OCCUPIED','RESERVED','CLEANING','MAINTENANCE','OUT_OF_SERVICE'].map(s=>({s,n:beds.filter(b=>b.status===s).length})),'s','n'))}</div></div><div style="margin-top:17px">${panel('All beds',`<div class="toolbar"><input id="bed-search" placeholder="Search bed or ward…"><select id="bed-filter"><option value="">All statuses</option>${['AVAILABLE','OCCUPIED','RESERVED','CLEANING','MAINTENANCE','OUT_OF_SERVICE'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="bed-table">${bedTable(beds)}</div>`)}</div>`;return;
 }
 if(p==='staff'){
  const rows=await api('/api/admin/staff');c.innerHTML=`<div class="section-title"><div><h3>Hospital staff accounts</h3><p>Create receptionist/admin accounts and control access.</p></div><button class="btn" data-action="add-staff">＋ Add staff</button></div>${panel('Staff directory',table(rows,[{key:'full_name',label:'Name'},{key:'username',label:'Username'},{key:'email',label:'Email'},{key:'phone',label:'Phone'},{key:'role',label:'Role'},{key:'account_status',label:'Status',render:r=>statusTag(r.account_status)},{key:'last_login_at',label:'Last login',render:r=>dateFmt(r.last_login_at)}],r=>`<button class="btn small ${r.account_status==='ACTIVE'?'danger':'secondary'}" data-action="staff-status" data-id="${r.user_id}" data-status="${r.account_status==='ACTIVE'?'DISABLED':'ACTIVE'}">${r.account_status==='ACTIVE'?'Disable':'Enable'}</button>`))}`;return;
 }
 if(p==='patients'){
  const rows=await api('/api/admin/patients');c.innerHTML=`<div class="section-title"><div><h3>Patient registry</h3><p>Search by UHID, patient name or phone.</p></div></div><div class="toolbar"><input id="patient-search" placeholder="Search patient…"><button class="btn secondary" data-action="refresh-patients">Refresh</button></div><div id="patient-table">${patientTable(rows)}</div>`;return;
 }
 if(p==='allocations'){
  const rows=await api('/api/admin/allocations?status=ALL');c.innerHTML=panel('Allocation monitor',table(rows,[{key:'allocation_id',label:'Allocation'},{key:'uhid',label:'UHID'},{key:'patient_name',label:'Patient'},{key:'ward_name',label:'Ward'},{key:'bed_code',label:'Bed'},{key:'admit_time',label:'Admitted',render:r=>dateFmt(r.admit_time)},{key:'discharge_time',label:'Discharged',render:r=>dateFmt(r.discharge_time)},{key:'status',label:'Status',render:r=>statusTag(r.status)},{key:'allocated_by_name',label:'Allocated by'}]));return;
 }
 if(p==='admin-waiting'){
  const rows=await api('/api/admin/waiting-list');c.innerHTML=panel('Hospital waiting list',table(rows,[{key:'patient_name',label:'Patient'},{key:'uhid',label:'UHID'},{key:'requested_category',label:'Ward'},{key:'esi_level',label:'ESI',render:r=>`<span class="tag ${r.esi_level<=2?'danger':'info'}">${r.esi_level}</span>`},{key:'priority_score',label:'Priority score'},{key:'added_at',label:'Added',render:r=>dateFmt(r.added_at)},{key:'status',label:'Status',render:r=>statusTag(r.status)}],r=>`<button class="btn small danger" data-action="admin-cancel-admission-request" data-id="${r.request_id}">Cancel request</button>`));return;
 }
 if(p==='reports'){
  const d=await api('/api/admin/reports/occupancy');c.innerHTML=`<div class="section-title"><div><h3>Occupancy and utilisation</h3><p>Ward-level capacity and admission activity.</p></div><div class="toolbar"><button class="btn secondary" data-action="download-occupancy">↓ Export CSV</button><button class="btn" data-action="print">Print / Save PDF</button></div></div><div class="grid kpis">${kpi('Total allocations',d.metrics.total_allocations,'▣')}${kpi('Average stay',`${d.metrics.average_stay_days||0} days`,'◷')}${kpi('Average wait',`${d.metrics.average_wait_minutes||0} min`,'⌛')}${kpi('Cleaning TAT',`${d.metrics.average_cleaning_minutes||0} min`,'⏱')}${kpi('Reporting period','30 days','▥')}</div><div class="grid two-col"><div>${panel('Occupied beds by ward',bars(d.byWard,'ward_name','occupied_beds'))}</div><div>${panel('Available beds by ward',bars(d.byWard,'ward_name','available_beds'))}</div></div><div style="margin-top:17px">${panel('Admissions and discharges — 30 days',bars(d.daily,'day','admissions'))}</div><div style="margin-top:17px">${panel('Ward occupancy data',table(d.byWard,[{key:'ward_name',label:'Ward'},{key:'ward_type',label:'Type'},{key:'capacity',label:'Capacity'},{key:'total_beds',label:'Beds'},{key:'available_beds',label:'Available'},{key:'occupied_beds',label:'Occupied'},{key:'unavailable_beds',label:'Unavailable'}]))}</div>`;return;
 }
 if(p==='audit'){
  const rows=await api('/api/admin/audit');c.innerHTML=`<div class="section-title"><div><h3>Audit trail</h3><p>Critical system actions with actor, timestamp and entity references.</p></div></div><div class="toolbar"><input id="audit-action" placeholder="Filter action…"><input id="audit-user" placeholder="Filter user…"><button class="btn secondary" data-action="filter-audit">Apply filters</button></div><div id="audit-table">${auditTable(rows)}</div>`;return;
 }
 if(p==='notifications'){
  const rows=await api('/api/admin/notifications');c.innerHTML=panel('Notifications',notificationList(rows));return;
 }
 if(p==='settings'){
  const s=await api('/api/admin/settings');c.innerHTML=`<div class="section-title"><div><h3>Hospital configuration</h3><p>Update the display profile for this single-hospital installation.</p></div></div><section class="panel"><form id="settings-form" class="form-grid"><div class="field"><label>HOSPITAL NAME</label><input name="hospitalName" value="${esc(s.hospital_name)}" required></div><div class="field"><label>TIME ZONE</label><input name="timezoneName" value="${esc(s.timezone_name)}" required></div><div class="field"><label>PHONE</label><input name="phone" value="${esc(s.phone)}"></div><div class="field"><label>EMAIL</label><input name="email" type="email" value="${esc(s.email)}"></div><div class="field full"><label>ADDRESS</label><textarea name="address" rows="3">${esc(s.address)}</textarea></div><div class="form-actions full"><button class="btn">Save settings</button></div></form></section>`;return;
 }
}
function bedTable(rows){
 const isAdmin=roleKey()==='ADMIN';
 return table(rows,[
  {key:'bed_code',label:'Bed'},
  {key:'ward_name',label:'Ward'},
  {key:'category',label:'Category'},
  {key:'daily_charge',label:'Daily charge',render:r=>money(r.daily_charge)},
  {key:'has_oxygen',label:'O₂',render:r=>r.has_oxygen?'Yes':'No'},
  {key:'has_ventilator',label:'Ventilator',render:r=>r.has_ventilator?'Yes':'No'},
  {key:'has_monitor',label:'Monitor',render:r=>r.has_monitor?'Yes':'No'},
  {key:'isolation_capable',label:'Isolation',render:r=>r.isolation_capable?'Yes':'No'},
  {key:'status',label:'Status',render:r=>statusTag(r.status)}
 ],r=>{
  const actions=[];
  if(isAdmin) actions.push(`<button class="btn small ghost" data-action="edit-bed" data-id="${r.bed_id}">Edit</button>`);
  if(r.status==='CLEANING') actions.push(`<button class="btn small secondary" data-action="bed-clean" data-id="${r.bed_id}">Mark clean & available</button>`);
  if(isAdmin&&['MAINTENANCE','OUT_OF_SERVICE'].includes(r.status)) actions.push(`<button class="btn small secondary" data-action="bed-status" data-id="${r.bed_id}" data-status="AVAILABLE">Mark available</button>`);
  return `<div class="table-actions">${actions.join('')||'<span class="muted">—</span>'}</div>`;
 });
}
function patientTable(rows){return table(rows,[{key:'uhid',label:'UHID'},{key:'full_name',label:'Patient'},{key:'age',label:'Age'},{key:'gender',label:'Gender'},{key:'phone',label:'Phone'},{key:'insurance_type',label:'Insurance'},{key:'record_status',label:'Status',render:r=>statusTag(r.record_status)}]);}
function auditTable(rows){return table(rows,[{key:'event_time',label:'Time',render:r=>dateFmt(r.event_time)},{key:'full_name',label:'User'},{key:'action',label:'Action',render:r=>statusTag(r.action)},{key:'entity_type',label:'Entity'},{key:'entity_id',label:'Entity ID'},{key:'ip_address',label:'IP'}]);}
function notificationList(rows){return rows.length?`<div class="alert-list">${rows.map(n=>`<div class="panel" style="box-shadow:none;display:flex;justify-content:space-between;gap:12px;align-items:center"><div><div style="font-weight:800">${esc(n.title)}</div><p class="muted" style="margin:5px 0">${esc(n.message)}</p><small class="muted">${dateFmt(n.created_at)}</small></div>${statusTag(n.is_read?'READ':'UNREAD')}</div>`).join('')}</div>`:'<div class="empty"><strong>All caught up</strong>No notifications right now.</div>';}
async function renderReception(c){
 const p=state.page;
 if(p==='overview'){
  const d=await api('/api/receptionist/stats');const [queue,beds]=await Promise.all([api('/api/receptionist/requests/queue'),api('/api/bed-board')]);
  c.innerHTML=`<div class="welcome"><div><div class="eyebrow">Front desk operations</div><h1>Welcome, ${esc((state.user.fullName||'Receptionist').split(' ')[0])}</h1><p>Prioritise critical requests and keep patient flow moving.</p></div><button class="btn" data-page="register">＋ New patient</button></div><div class="grid kpis">${kpi('Pending requests',d.pendingRequests,'☷')}${kpi('Emergency cases',d.emergencyCases,'✚')}${kpi('Available beds',d.availableBeds,'▦')}${kpi('Active admissions',d.activeAdmissions,'▣')}</div><div class="grid two-col"><div>${panel('Priority admission queue',queue.length?table(queue.slice(0,8),[{key:'patient_name',label:'Patient'},{key:'uhid',label:'UHID'},{key:'requested_category',label:'Ward'},{key:'esi_level',label:'ESI',render:r=>`<span class="tag ${r.esi_level<=2?'danger':'info'}">ESI ${r.esi_level}</span>`},{key:'status',label:'Status',render:r=>statusTag(r.status)}],r=>`<button class="btn small" data-action="allocate" data-id="${r.request_id}">Suggest bed</button>`):'<div class="empty">No pending requests.</div>')}</div><div>${panel('Bed status at a glance',bars(['AVAILABLE','OCCUPIED','RESERVED','CLEANING','MAINTENANCE'].map(s=>({s,n:beds.filter(b=>b.status===s).length})),'s','n'))}</div></div>`;return;
 }
 if(p==='patients'){
  const rows=await api('/api/receptionist/patients');state.cache.receptionPatients=rows;c.innerHTML=`<div class="section-title"><div><h3>Patient registry</h3><p>Search by UHID, name or phone. Select a patient to inspect their record and start an admission request.</p></div><button class="btn" data-page="register">＋ Register patient</button></div><div class="toolbar"><input id="reception-patient-search" placeholder="Search UHID, patient name or phone…"><button class="btn secondary" data-action="refresh-page">Refresh</button></div><div id="reception-patient-table">${table(rows,[{key:'uhid',label:'UHID'},{key:'full_name',label:'Patient'},{key:'age',label:'Age'},{key:'gender',label:'Gender'},{key:'phone',label:'Phone'},{key:'insurance_type',label:'Payment type'},{key:'record_status',label:'Status',render:r=>statusTag(r.record_status)}],r=>`<button class="btn small" data-action="view-reception-patient" data-id="${r.patient_id}">View / Admit</button>`)}</div>`;return;
 }
 if(p==='register'){
  c.innerHTML=`<div class="section-title"><div><h3>Register a patient</h3><p>UHID and Patient User ID are generated automatically. Receptionist sets the initial login password here. No OTP is required.</p></div></div><section class="panel"><form id="patient-form" class="form-grid"><div class="field"><label>FULL NAME *</label><input name="fullName" required></div><div class="field"><label>DATE OF BIRTH *</label><input name="dateOfBirth" type="date" max="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>GENDER *</label><select name="gender" required><option value="">Select</option><option>MALE</option><option>FEMALE</option><option>OTHER</option><option>UNDISCLOSED</option></select></div><div class="field"><label>PHONE *</label><input name="phone" required></div><div class="field"><label>EMAIL</label><input name="email" type="email"></div><div class="field"><label>BLOOD GROUP</label><select name="bloodGroup">${['UNKNOWN','A_POS','A_NEG','B_POS','B_NEG','AB_POS','AB_NEG','O_POS','O_NEG'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>ADDRESS</label><textarea name="address" rows="2"></textarea></div><div class="field"><label>EMERGENCY CONTACT NAME</label><input name="emergencyContactName"></div><div class="field"><label>EMERGENCY CONTACT PHONE</label><input name="emergencyContactPhone"></div><div class="field"><label>ID PROOF TYPE</label><select name="idProofType">${['NONE','AADHAAR','ABHA','PASSPORT','VOTER_ID','OTHER'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>INSURANCE / PAYMENT</label><select name="insuranceType">${['CASH','PM_JAY','PRIVATE','CORPORATE','OTHER'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>KNOWN ALLERGIES</label><input name="allergies"></div><div class="field"><label>CHRONIC CONDITIONS</label><input name="chronicConditions"></div><div class="field full"><h4>Patient login credentials</h4><p class="muted">A numeric User ID will be generated after saving. Give this ID and the password to the patient.</p></div><div class="field"><label>SET PASSWORD * (MINIMUM 10 CHARACTERS)</label><input name="password" type="password" minlength="10" autocomplete="new-password" required></div><div class="field"><label>CONFIRM PASSWORD *</label><input name="confirmPassword" type="password" minlength="10" autocomplete="new-password" required></div><div class="field full"><label><input type="checkbox" name="consentGranted" required> Patient/attendant consent captured for processing this information and creation of the patient portal account.</label></div><div class="form-actions full"><button class="btn">Register patient & create login</button></div></form></section>`;return;
 }
 if(p==='queue'){
  const rows=await api('/api/receptionist/requests/queue');c.innerHTML=`<div class="section-title"><div><h3>Admission requests</h3><p>ESI level is the primary priority. Lower ESI number means higher urgency.</p></div><button class="btn secondary" data-action="refresh-page">Refresh queue</button></div>${panel('Live priority queue',table(rows,[{key:'patient_name',label:'Patient'},{key:'uhid',label:'UHID'},{key:'phone',label:'Phone'},{key:'requested_category',label:'Required ward'},{key:'esi_level',label:'Triage',render:r=>`<span class="tag ${r.esi_level<=2?'danger':'info'}">ESI ${r.esi_level} · ${r.emergency_flag?'Emergency':'Routine'}</span>`},{key:'status',label:'Status',render:r=>statusTag(r.status)},{key:'requested_at',label:'Requested',render:r=>dateFmt(r.requested_at)}],r=>`<div class="table-actions">${r.status==='PENDING_VERIFICATION'?`<button class="btn small secondary" data-action="verify-request" data-id="${r.request_id}">Verify triage</button>`:''}${['VERIFIED','WAITING'].includes(r.status)?`<button class="btn small" data-action="allocate" data-id="${r.request_id}">Find bed</button>`:''}${r.status==='VERIFIED'?`<button class="btn small ghost" data-action="waitlist" data-id="${r.request_id}">Waitlist</button>`:''}<button class="btn small danger" data-action="cancel-admission-request" data-id="${r.request_id}">Cancel</button></div>`))}`;return;
 }
 if(p==='beds'){
  const rows=await api('/api/bed-board');state.cache.beds=rows;c.innerHTML=`<div class="section-title"><div><h3>Bed availability board</h3><p>Live ward inventory. Cleaning beds can be released by housekeeping.</p></div><button class="btn secondary" data-action="refresh-page">Refresh</button></div><div class="toolbar"><input id="bed-search" placeholder="Search bed or ward…"><select id="bed-filter"><option value="">All statuses</option>${['AVAILABLE','OCCUPIED','RESERVED','CLEANING','MAINTENANCE','OUT_OF_SERVICE'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="bed-table">${bedTable(rows)}</div>`;return;
 }
 if(p==='active'){
  const rows=await api('/api/receptionist/admissions/active');c.innerHTML=`<div class="section-title"><div><h3>Active admissions</h3><p>Transfer a patient or record the discharge and release the bed to Cleaning.</p></div><button class="btn secondary" data-action="refresh-page">Refresh</button></div>${panel('Currently admitted patients',table(rows,[{key:'uhid',label:'UHID'},{key:'patient_name',label:'Patient'},{key:'phone',label:'Phone'},{key:'ward_name',label:'Ward'},{key:'bed_code',label:'Bed'},{key:'admit_time',label:'Admitted',render:r=>dateFmt(r.admit_time)},{key:'expected_discharge',label:'Expected discharge',render:r=>dateFmt(r.expected_discharge)}],r=>`<div class="table-actions"><button class="btn small secondary" data-action="transfer" data-id="${r.allocation_id}">Transfer</button><button class="btn small danger" data-action="discharge" data-id="${r.allocation_id}">Discharge</button></div>`))}`;return;
 }
 if(p==='waiting'){
  const rows=await api('/api/receptionist/waiting-list');c.innerHTML=panel('Priority waiting list',table(rows,[{key:'patient_name',label:'Patient'},{key:'uhid',label:'UHID'},{key:'requested_category',label:'Required ward'},{key:'esi_level',label:'ESI',render:r=>`<span class="tag ${r.esi_level<=2?'danger':'info'}">${r.esi_level}</span>`},{key:'priority_score',label:'Priority score'},{key:'added_at',label:'Added',render:r=>dateFmt(r.added_at)},{key:'status',label:'Status',render:r=>statusTag(r.status)}],r=>`<div class="table-actions"><button class="btn small" data-action="allocate" data-id="${r.request_id}">Find bed</button><button class="btn small danger" data-action="cancel-admission-request" data-id="${r.request_id}">Cancel</button></div>`));return;
 }
 if(p==='billing'){
  const rows=await api('/api/receptionist/billing/invoices');c.innerHTML=`<div class="section-title"><div><h3>Billing ledger</h3><p>Record offline payments or collect online using Razorpay Checkout. Online payments are confirmed by the server before an invoice is marked paid.</p></div><div class="toolbar"><button class="btn secondary" data-action="billing-csv">Export CSV</button></div></div>${panel('Invoices',table(rows,[{key:'invoice_no',label:'Invoice'},{key:'uhid',label:'UHID'},{key:'patient_name',label:'Patient'},{key:'invoice_date',label:'Date',render:r=>dateFmt(r.invoice_date)},{key:'total_amount',label:'Total',render:r=>money(r.total_amount)},{key:'amount_paid',label:'Paid',render:r=>money(r.amount_paid)},{key:'balance_due',label:'Balance',render:r=>money(r.balance_due)},{key:'invoice_status',label:'Status',render:r=>statusTag(r.invoice_status)}],r=>Number(r.balance_due)>0?`<div class="table-actions"><button class="btn small" data-action="razorpay-pay" data-id="${r.invoice_id}">Pay online</button><button class="btn small secondary" data-action="payment" data-id="${r.invoice_id}" data-balance="${r.balance_due}">Record offline</button></div>`:`<span class="tag ok">Settled</span>`))}`;return;
 }
 if(p==='notifications'){
  const rows=await api('/api/receptionist/notifications');c.innerHTML=panel('Notifications',notificationList(rows));return;
 }
}
async function renderPatient(c){
 const p=state.page;
 if(p==='overview'||p==='admission'){
  const [profile,adm]=await Promise.all([api('/api/patient/profile'),api('/api/patient/admission')]);const a=adm.activeAdmission;
  if(p==='overview')c.innerHTML=`<div class="welcome"><div><div class="eyebrow">Patient portal · ${esc(profile.uhid)}</div><h1>Welcome, ${esc(profile.full_name.split(' ')[0])}</h1><p>${a?.bed_code?`You are admitted in ${esc(a.ward_name)} · Bed ${esc(a.bed_code)}`:'No active admission. You can submit a request online.'}</p></div><button class="btn" data-page="request">＋ Request admission</button></div><div class="grid kpis">${kpi('UHID',profile.uhid,'♙','Your hospital identifier')}${kpi('Admission status',a?'Admitted':'Not admitted','▣')}${kpi('Open requests',adm.requests.filter(x=>['PENDING_VERIFICATION','VERIFIED','WAITING'].includes(x.status)).length,'☷')}${kpi('Age',profile.age,'◷','Years')}</div><div class="grid two-col">${panel('Current admission',a?table([a],[{key:'ward_name',label:'Ward'},{key:'bed_code',label:'Bed'},{key:'admit_time',label:'Admitted',render:r=>dateFmt(r.admit_time)},{key:'daily_charge',label:'Daily charge',render:r=>money(r.daily_charge)}]):'<div class="empty"><strong>No active admission</strong>Admission details appear here after a bed is allocated.</div>')}${panel('Recent requests',table(adm.requests.slice(0,5),[{key:'requested_category',label:'Ward'},{key:'esi_level',label:'ESI'},{key:'status',label:'Status',render:r=>statusTag(r.status)},{key:'requested_at',label:'Requested',render:r=>dateFmt(r.requested_at)}]))}</div>`;
  else c.innerHTML=`<div class="section-title"><div><h3>My current admission</h3><p>Admission details and request status.</p></div></div>${a?panel('Active bed assignment',table([a],[{key:'ward_name',label:'Ward'},{key:'ward_type',label:'Type'},{key:'bed_code',label:'Bed'},{key:'floor_label',label:'Floor'},{key:'admit_time',label:'Admit time',render:r=>dateFmt(r.admit_time)},{key:'expected_discharge',label:'Expected discharge',render:r=>dateFmt(r.expected_discharge)},{key:'daily_charge',label:'Daily charge',render:r=>money(r.daily_charge)}])):'<div class="empty"><strong>No active admission</strong>You are not currently assigned to a bed.</div>'}<div style="margin-top:17px">${panel('Admission request timeline',table(adm.requests,[{key:'requested_at',label:'Date',render:r=>dateFmt(r.requested_at)},{key:'requested_category',label:'Requested ward'},{key:'esi_level',label:'ESI'},{key:'reason',label:'Reason'},{key:'status',label:'Status',render:r=>statusTag(r.status)}]))}</div>`;return;
 }
 if(p==='request'){
  const wards=await api('/api/wards');const doctors=await api('/api/doctors');c.innerHTML=`<div class="section-title"><div><h3>Request admission</h3><p>Your request is sent to reception for verification. ESI level must be set by the treating clinical team.</p></div></div><section class="panel"><form id="admission-request-form" class="form-grid"><div class="field"><label>PREFERRED WARD *</label><select name="requestedCategory" required>${[...new Set(wards.map(w=>w.ward_type))].map(w=>`<option>${esc(w)}</option>`).join('')}</select></div><div class="field"><label>TRIAGE LEVEL</label><p class="muted">A provisional ESI 5 is used until hospital staff assess and verify the request.</p></div><div class="field"><label>DOCTOR (OPTIONAL)</label><select name="doctorId"><option value="">Not selected</option>${doctors.map(d=>`<option value="${d.doctor_id}">${esc(d.full_name)} · ${esc(d.department||'')}</option>`).join('')}</select></div><div class="field"><label>EXPECTED STAY (DAYS)</label><input name="expectedStayDays" type="number" min="1" max="365"></div><div class="field full"><label>REASON FOR ADMISSION *</label><textarea name="reason" rows="3" required></textarea></div><div class="field"><label><input type="checkbox" name="requiresOxygen"> Requires oxygen</label><label><input type="checkbox" name="requiresVentilator"> Requires ventilator</label><label><input type="checkbox" name="requiresMonitor"> Requires monitor</label><label><input type="checkbox" name="isolationRequired"> Isolation required</label></div><div class="field"><label>Clinical isolation verification</label><p class="muted">This is verified by hospital staff, not by a patient account.</p></div><div class="form-actions full"><button class="btn">Submit admission request</button></div></form></section>`;return;
 }
 if(p==='history'){
  const rows=await api('/api/patient/history');c.innerHTML=panel('Admission history',table(rows,[{key:'admit_time',label:'Admitted',render:r=>dateFmt(r.admit_time)},{key:'discharge_time',label:'Discharged',render:r=>dateFmt(r.discharge_time)},{key:'ward_name',label:'Ward'},{key:'bed_code',label:'Bed'},{key:'discharge_type',label:'Discharge type'},{key:'status',label:'Status',render:r=>statusTag(r.status)}]));return;
 }
 if(p==='bills'){
  const rows=await api('/api/patient/bills');c.innerHTML=panel('My invoices',table(rows,[{key:'invoice_no',label:'Invoice'},{key:'invoice_date',label:'Date',render:r=>dateFmt(r.invoice_date)},{key:'total_amount',label:'Total',render:r=>money(r.total_amount)},{key:'net_amount_paid',label:'Paid',render:r=>money(r.net_amount_paid)},{key:'balance_due',label:'Balance',render:r=>money(r.balance_due)},{key:'invoice_status',label:'Status',render:r=>statusTag(r.invoice_status)}],r=>Number(r.balance_due)>0?`<div class="table-actions"><button class="btn small" data-action="patient-pay-online" data-id="${r.invoice_id}">Pay online</button><button class="btn small secondary" data-action="patient-bill" data-id="${r.invoice_id}">Details</button></div>`:`<button class="btn small secondary" data-action="patient-bill" data-id="${r.invoice_id}">Details</button>`));return;
 }
 if(p==='availability'){
  const rows=await api('/api/patient/bed-availability');c.innerHTML=panel('Bed availability by ward',`<p class="muted">Read-only summary. Availability can change quickly and is not a reservation.</p>${table(rows,[{key:'ward_name',label:'Ward'},{key:'ward_type',label:'Type'},{key:'total_beds',label:'Total beds'},{key:'available_beds',label:'Available'},{key:'occupied_beds',label:'Occupied'},{key:'unavailable_beds',label:'Unavailable'}])}`);return;
 }
 if(p==='notifications'){
  const rows=await api('/api/patient/notifications');c.innerHTML=panel('Notifications',notificationList(rows));return;
 }
 if(p==='profile'){
  const r=await api('/api/patient/profile');c.innerHTML=panel('My profile',table([r],[{key:'uhid',label:'UHID'},{key:'full_name',label:'Name'},{key:'date_of_birth',label:'Date of birth'},{key:'age',label:'Age'},{key:'gender',label:'Gender'},{key:'blood_group',label:'Blood group'},{key:'phone',label:'Phone'},{key:'email',label:'Email'},{key:'insurance_type',label:'Payment type'}]));return;
 }
}
function openModal(title,body){const layer=document.createElement('div');layer.className='modal-backdrop';layer.id='modal';layer.innerHTML=`<section class="modal"><div class="modal-head"><h3>${esc(title)}</h3><button class="icon-btn" data-action="close-modal">×</button></div>${body}</section>`;document.body.append(layer);}
function closeModal(){ $('#modal')?.remove(); }
function formObject(form){const o={};for(const [k,v] of new FormData(form).entries()){if(k in o){o[k]=Array.isArray(o[k])?[...o[k],v]:[o[k],v];}else o[k]=v;}form.querySelectorAll('input[type=checkbox]').forEach(x=>o[x.name]=x.checked);form.querySelectorAll('input[type=number],input[type=hidden][name$=Id],input[type=hidden][name=patientId],select[name=esiLevel]').forEach(x=>{if(o[x.name]!==undefined&&o[x.name]!=='')o[x.name]=Number(o[x.name]);});form.querySelectorAll('select[name$="Id"]').forEach(x=>{if(o[x.name]==='')o[x.name]=null;else if(o[x.name]!==undefined)o[x.name]=Number(o[x.name]);});return o;}
function wardForm(w={}){openModal(w.ward_id?'Edit ward':'Add ward',`<form id="ward-modal-form" class="form-grid"><div class="field"><label>WARD NAME *</label><input name="wardName" value="${esc(w.ward_name||'')}" required></div><div class="field"><label>WARD TYPE *</label><select name="wardType">${['GENERAL','SEMI-PRIVATE','PRIVATE','ICU','HDU','CCU','NICU','PEDIATRIC','MATERNITY','ISOLATION','EMERGENCY','SURGICAL','ORTHOPEDIC'].map(x=>`<option ${String(w.ward_type||'').toUpperCase()===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>FLOOR</label><input name="floorLabel" value="${esc(w.floor_label||'')}"></div><div class="field"><label>GENDER POLICY</label><select name="genderPolicy">${['ANY','MALE_ONLY','FEMALE_ONLY'].map(x=>`<option ${w.gender_policy===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>CAPACITY</label><input name="capacity" type="number" min="0" value="${esc(w.capacity??0)}"></div>${w.ward_id?`<div class="field"><label>STATUS</label><select name="status"><option ${w.status==='ACTIVE'?'selected':''}>ACTIVE</option><option ${w.status==='INACTIVE'?'selected':''}>INACTIVE</option></select></div>`:''}<div class="form-actions full"><button class="btn">Save ward</button></div></form>`);$('#ward-modal-form').onsubmit=async e=>{e.preventDefault();const b=formObject(e.currentTarget);await runAction(()=>api(w.ward_id?`/api/admin/wards/${w.ward_id}`:'/api/admin/wards',{method:w.ward_id?'PUT':'POST',body:JSON.stringify(b)}), 'Ward saved.');};}
function bedForm(b={},wards=state.cache.wards||[]){
 const checked=(field)=>{const v=b[field];return v===true||v===1||v==='1'||String(v).toLowerCase()==='true';};
 openModal(b.bed_id?'Edit bed':'Add bed',`<form id="bed-modal-form" class="form-grid">
  <div class="field"><label>BED CODE *</label><input name="bedCode" maxlength="30" value="${esc(b.bed_code||'')}" required></div>
  <div class="field"><label>WARD *</label><select name="wardId" required>${wards.map(w=>`<option value="${w.ward_id}" ${Number(b.ward_id)===Number(w.ward_id)?'selected':''}>${esc(w.ward_name)}</option>`).join('')}</select></div>
  <div class="field"><label>CATEGORY *</label><input name="category" maxlength="40" value="${esc(b.category||'GENERAL')}" required></div>
  <div class="field"><label>FLOOR</label><input name="floorLabel" maxlength="30" value="${esc(b.floor_label||'')}"></div>
  <div class="field"><label>DAILY CHARGE (₹)</label><input name="dailyCharge" type="number" min="0" max="999999999" step="0.01" value="${esc(b.daily_charge??0)}" required></div>
  <div class="field"><label>FACILITIES</label>
   ${[['hasOxygen','has_oxygen','Oxygen'],['hasVentilator','has_ventilator','Ventilator'],['hasMonitor','has_monitor','Patient monitor'],['attachedBathroom','attached_bathroom','Attached bathroom'],['isolationCapable','isolation_capable','Isolation capable']].map(([key,field,label])=>`<label><input type="checkbox" name="${key}" ${checked(field)?'checked':''}> ${label}</label>`).join('')}
  </div>
  <div class="field full"><label>NOTES</label><textarea name="notes" maxlength="500">${esc(b.notes||'')}</textarea></div>
  <div class="form-actions full"><button class="btn" type="submit">Save bed</button></div>
 </form>`);
 $('#bed-modal-form').onsubmit=async e=>{e.preventDefault();const data=formObject(e.currentTarget);await runAction(()=>api(b.bed_id?`/api/admin/beds/${b.bed_id}`:'/api/admin/beds',{method:b.bed_id?'PUT':'POST',body:JSON.stringify(data)}),'Bed saved.');};
}
function staffForm(){openModal('Create staff account',`<form id="staff-modal-form" class="form-grid"><div class="field"><label>FULL NAME *</label><input name="fullName" required></div><div class="field"><label>USERNAME *</label><input name="username" required></div><div class="field"><label>EMAIL</label><input name="email" type="email"></div><div class="field"><label>PHONE</label><input name="phone"></div><div class="field"><label>ROLE</label><select name="role"><option>RECEPTIONIST</option><option>ADMIN</option></select></div><div class="field"><label>TEMPORARY PASSWORD *</label><input name="password" type="password" minlength="10" required></div><div class="form-actions full"><button class="btn">Create account</button></div></form>`);$('#staff-modal-form').onsubmit=async e=>{e.preventDefault();await runAction(()=>api('/api/admin/staff',{method:'POST',body:JSON.stringify(formObject(e.currentTarget))}),'Staff account created.');};}
async function runAction(fn,success){try{const r=await fn();closeModal();toast(r?.message||success||'Completed.');await renderPage();}catch(e){toast(e.message,'error');}}
async function allocateRequest(id){try{const options=await api(`/api/receptionist/requests/${id}/suggestions`);if(!options.length){if(confirm('No compatible available bed found. Add this request to the waiting list?'))await runAction(()=>api(`/api/receptionist/requests/${id}/waitlist`,{method:'POST'}),'Added to waiting list.');return;}const best=options[0];const alternative=String(best.ward_type).toUpperCase()!==String(best.requested_category||'').toUpperCase();if(alternative&&!confirm(`Preferred ward is full. Suggested alternative: ${best.ward_name} (${best.ward_type}), match ${best.matchScore}/100. Confirm this alternative?`))return;const reason=prompt(`Suggested bed: ${best.bed_code} · ${best.ward_name} · score ${best.matchScore}/100\nEnter allocation reason:`);if(!reason)return;await runAction(()=>api(`/api/receptionist/requests/${id}/allocate`,{method:'POST',body:JSON.stringify({bedId:best.bed_id,reason})}),'Bed allocated.');}catch(e){toast(e.message,'error');}}
async function transfer(id){try{const beds=await api('/api/bed-board?status=AVAILABLE');const options=beds.filter(b=>b.status==='AVAILABLE');if(!options.length){toast('No available destination beds.','error');return;}const listing=options.slice(0,30).map(b=>`${b.bed_id}: ${b.bed_code} · ${b.ward_name}`).join('\n');const bedId=prompt(`Choose destination bed ID:\n${listing}`);if(!bedId)return;const reason=prompt('Mandatory transfer reason:');if(!reason)return;await runAction(()=>api(`/api/receptionist/allocations/${id}/transfer`,{method:'PUT',body:JSON.stringify({bedId:Number(bedId),reason})}),'Patient transferred.');}catch(e){toast(e.message,'error');}}
async function discharge(id){const dischargeType=prompt('Discharge type: RECOVERED, REFERRED, LAMA, DECEASED or OTHER','RECOVERED');if(!dischargeType)return;const reason=prompt('Mandatory discharge reason:');if(!reason)return;await runAction(()=>api(`/api/receptionist/allocations/${id}/discharge`,{method:'PUT',body:JSON.stringify({dischargeType,reason})}),'Discharge recorded.');}
async function patientBill(id){try{const d=await api(`/api/patient/bills/${id}`);openModal(`Invoice ${d.invoice.invoice_no}`,`${table(d.items,[{key:'description',label:'Description'},{key:'quantity',label:'Quantity'},{key:'unit_price',label:'Rate',render:r=>money(r.unit_price)},{key:'line_total',label:'Total',render:r=>money(r.line_total)}])}<div style="margin-top:15px">Total ${money(d.invoice.total_amount)} · Paid ${money(d.invoice.net_amount_paid)} · Due ${money(d.invoice.balance_due)}</div>${Number(d.invoice.balance_due)>0?`<div class="form-actions"><button class="btn" data-action="patient-pay-online" data-id="${id}">Pay outstanding balance</button></div>`:''}`);}catch(e){toast(e.message,'error');}}
async function loadRazorpayCheckout(){
 if(window.Razorpay)return;
 await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=resolve;script.onerror=()=>reject(new Error('Razorpay Checkout could not be loaded. Check your internet connection.'));document.head.appendChild(script);});
}
async function startRazorpayPayment(invoiceId,patientMode=false){
 try{
  const orderPath=patientMode?`/api/patient/bills/${Number(invoiceId)}/razorpay/orders`:'/api/receptionist/billing/razorpay/orders';
  const verifyPath=patientMode?'/api/patient/bills/razorpay/verify':'/api/receptionist/billing/razorpay/verify';
  const order=await api(orderPath,{method:'POST',body:JSON.stringify(patientMode?{}:{invoiceId:Number(invoiceId)})});
  await loadRazorpayCheckout();
  const checkout=new Razorpay({key:order.keyId,amount:order.amount,currency:order.currency,name:'IHBAS Hospital',description:`Invoice ${order.invoiceNo}`,order_id:order.razorpayOrderId,prefill:{name:order.patientName||'',email:order.email||'',contact:order.phone||''},notes:{invoice_no:order.invoiceNo},theme:{color:'#2563eb'},modal:{ondismiss:()=>toast('Payment window closed. The invoice remains unpaid until payment is confirmed.','error')},handler:async response=>{
   try{const result=await api(verifyPath,{method:'POST',body:JSON.stringify({paymentOrderId:order.paymentOrderId,razorpayPaymentId:response.razorpay_payment_id,razorpaySignature:response.razorpay_signature})});toast(result.message||'Payment verification completed.',result.status==='SUCCESS'?'success':'error');await renderPage();}
   catch(err){toast(err.message,'error');}
  }});
  checkout.on('payment.failed',response=>toast(response?.error?.description||'Razorpay reports that the payment failed. The invoice was not marked paid.','error'));
  checkout.open();
 }catch(err){toast(err.message,'error');}
}
async function forgotPassword(){openModal('Reset password',`<form id="reset-otp-form"><div class="field"><label>ACCOUNT PHONE</label><input name="phone" required></div><button class="btn">Request OTP</button></form>`);$('#reset-otp-form').onsubmit=async e=>{e.preventDefault();try{const phone=e.currentTarget.elements.phone.value;const r=await api('/api/auth/password/otp/request',{method:'POST',body:JSON.stringify({phone})});closeModal();openModal('Set new password',`<p class="muted">${esc(r.message)} ${r.demoOtp?`Demo OTP: <b>${esc(r.demoOtp)}</b>`:''}</p><form id="reset-password-form"><input type="hidden" name="phone" value="${esc(phone)}"><div class="field"><label>OTP</label><input name="otp" required></div><div class="field"><label>NEW PASSWORD</label><input type="password" name="newPassword" minlength="10" required></div><button class="btn">Reset password</button></form>`);$('#reset-password-form').onsubmit=async ev=>{ev.preventDefault();await runAction(()=>api('/api/auth/password/reset',{method:'POST',body:JSON.stringify(formObject(ev.currentTarget))}),'Password reset. Sign in again.');};}catch(err){toast(err.message,'error');}};}

// Single delegated click handler keeps dynamically rendered pages interactive.
document.addEventListener('click',async e=>{
 const page=e.target.closest('[data-page]');if(page){state.page=page.dataset.page;state.sidebarOpen=false;renderShell();return;}
 const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;
 try{
  switch(b.dataset.action){
   case 'logout':logout();break;case 'toggle-sidebar':state.sidebarCollapsed=!state.sidebarCollapsed;localStorage.setItem('ihbas_sidebar_collapsed',state.sidebarCollapsed?'1':'0');renderShell();break;case 'menu':state.sidebarOpen=true;renderShell();break;case 'close-menu':state.sidebarOpen=false;renderShell();break;case 'close-modal':closeModal();break;
   case 'forgot':forgotPassword();break;
   case 'create-patient-account':{
    const patient=await api(`/api/receptionist/patients/${id}`);
    closeModal();
    openModal('Create patient login',`<p class="muted">Create credentials for ${esc(patient.full_name)} (${esc(patient.uhid)}). No OTP is required.</p><form id="existing-patient-account-form" class="form-grid"><div class="field full"><label>EMAIL (OPTIONAL)</label><input name="email" type="email" value="${esc(patient.email||'')}"></div><div class="field"><label>SET PASSWORD *</label><input name="password" type="password" minlength="10" required autocomplete="new-password"></div><div class="field"><label>CONFIRM PASSWORD *</label><input name="confirmPassword" type="password" minlength="10" required autocomplete="new-password"></div><div class="form-actions full"><button class="btn">Create login credentials</button></div></form>`);
    $('#existing-patient-account-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget;const data=formObject(form);if(data.password!==data.confirmPassword){toast('Password and confirm password do not match.','error');return;}try{const result=await api(`/api/receptionist/patients/${id}/account`,{method:'POST',body:JSON.stringify(data)});closeModal();await renderPage();openModal('Patient login created',`<p>Share these credentials securely with the patient.</p><div class="panel"><p>Patient: <b>${esc(patient.full_name)}</b></p><p>UHID: <b>${esc(result.uhid)}</b></p><p>User ID / Login ID: <b>${esc(result.loginId)}</b></p><p>Username: <b>${esc(result.username)}</b></p><p>Initial password: <b>${esc(data.password)}</b></p></div><p class="muted">The password is shown only in this confirmation. It is stored as a BCrypt hash.</p>`);}catch(err){toast(err.message,'error');}};
    break;
   }
   case 'download-patient-document':{const resp=await fetch(`/api/receptionist/patients/${b.dataset.patientId}/documents/${id}/download`,{headers:{Authorization:`Bearer ${state.token}`}});if(!resp.ok)throw new Error('Document download failed.');const blob=await resp.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='patient-document';a.click();URL.revokeObjectURL(url);break;}
   case 'view-reception-patient':{const patient=await api(`/api/receptionist/patients/${id}`);const docs=await api(`/api/receptionist/patients/${id}/documents`);openModal(`Patient · ${patient.uhid}`,`<div class="grid two-col"><div><b>${esc(patient.full_name)}</b><p>${esc(patient.phone||'')}</p><p>${esc(patient.email||'')}</p><p>${esc(patient.gender)} · ${esc(patient.age)} years</p></div><div><p>Insurance: ${esc(patient.insurance_type||'—')}</p><p>Allergies: ${esc(patient.allergies||'—')}</p><p>Conditions: ${esc(patient.chronic_conditions||'—')}</p></div></div><section class="panel"><h3>Patient portal account</h3>${patient.user_id?`<p>Account linked · User ID: <b>${esc(patient.user_id)}</b> · Login ID: <b>${esc(patient.login_username||'—')}</b></p>`:`<p class="muted">No login account is linked to this patient record.</p><button class="btn" data-action="create-patient-account" data-id="${patient.patient_id}">＋ Create patient login</button>`}</section><section class="panel"><h3>Patient documents</h3>${docs.length?table(docs,[{key:'original_filename',label:'File'},{key:'document_type',label:'Type'},{key:'uploaded_at',label:'Uploaded',render:r=>dateFmt(r.uploaded_at)}],r=>`<a class="btn small secondary" href="/api/receptionist/patients/${patient.patient_id}/documents/${r.document_id}/download" target="_blank">Download</a>`):'<p class="muted">No documents uploaded.</p>'}<form id="patient-document-form" class="form-grid"><div class="field"><label>DOCUMENT TYPE</label><select name="documentType"><option>IDENTITY</option><option>INSURANCE</option><option>REFERRAL</option><option>CONSENT</option><option>OTHER</option></select></div><div class="field"><label>FILE (PDF/JPG/PNG · MAX 10 MB)</label><input type="file" name="file" accept=".pdf,.jpg,.jpeg,.png" required></div><button class="btn">Upload document</button></form></section><div class="form-actions"><button class="btn" data-action="create-admission-for-patient" data-id="${patient.patient_id}">Create admission request</button></div>`);$('#patient-document-form').onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(ev.currentTarget);try{const resp=await fetch(`/api/receptionist/patients/${patient.patient_id}/documents`,{method:'POST',headers:{Authorization:`Bearer ${state.token}`},body:fd});const data=await resp.json();if(!resp.ok)throw new Error(data.message||'Upload failed');toast(data.message||'Document uploaded.');closeModal();}catch(err){toast(err.message,'error');}};break;}
   case 'create-admission-for-patient':{const patientId=Number(id);const wards=await api('/api/wards');const doctors=await api('/api/doctors');openModal('Create admission request',`<form id="reception-admission-form" class="form-grid"><input type="hidden" name="patientId" value="${patientId}"><div class="field"><label>WARD CATEGORY *</label><select name="requestedCategory">${[...new Set(wards.map(w=>w.ward_type))].map(w=>`<option>${esc(w)}</option>`).join('')}</select></div><div class="field"><label>CLINICAL ESI LEVEL *</label><select name="esiLevel"><option value="1">ESI 1 · Immediate</option><option value="2">ESI 2 · Emergent</option><option value="3" selected>ESI 3 · Urgent</option><option value="4">ESI 4 · Less urgent</option><option value="5">ESI 5 · Non-urgent</option></select></div><div class="field"><label>DOCTOR</label><select name="doctorId"><option value="">Not selected</option>${doctors.map(d=>`<option value="${d.doctor_id}">${esc(d.full_name)}</option>`).join('')}</select></div><div class="field"><label>EXPECTED STAY (DAYS)</label><input type="number" min="1" max="365" name="expectedStayDays"></div><div class="field full"><label>REASON *</label><textarea name="reason" required></textarea></div><div class="field"><label><input type="checkbox" name="requiresOxygen"> Oxygen</label><label><input type="checkbox" name="requiresVentilator"> Ventilator</label><label><input type="checkbox" name="requiresMonitor"> Monitor</label><label><input type="checkbox" name="isolationRequired"> Isolation</label><label><input type="checkbox" name="clinicalIsolationVerified"> Isolation clinically verified</label></div><div class="form-actions full"><button class="btn">Create request</button></div></form>`);$('#reception-admission-form').onsubmit=async ev=>{ev.preventDefault();await runAction(()=>api('/api/receptionist/requests',{method:'POST',body:JSON.stringify(formObject(ev.currentTarget))}),'Admission request created.');};break;}
   case 'add-ward':wardForm();break;case 'edit-ward':wardForm(state.cache.wards.find(x=>Number(x.ward_id)===Number(id)));break;
   case 'add-bed':bedForm();break;case 'edit-bed':bedForm(state.cache.beds.find(x=>Number(x.bed_id)===Number(id)));break;
   case 'add-staff':staffForm();break;
   case 'deactivate-ward':if(confirm('Deactivate this ward? Occupied/reserved wards cannot be deactivated.'))await runAction(()=>api(`/api/admin/wards/${id}`,{method:'DELETE'}),'Ward deactivated.');break;
   case 'staff-status':if(confirm(`Set staff status to ${b.dataset.status}?`))await runAction(()=>api(`/api/admin/staff/${id}/status`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status})}),'Staff status updated.');break;
   case 'bed-clean':
    if(!confirm('Confirm that housekeeping has completed cleaning for this bed?'))break;
    await runAction(()=>api(`/api/receptionist/beds/${id}/clean`,{method:'POST'}),'Bed marked clean and available.');break;
   case 'bed-status':
    if(roleKey()!=='ADMIN')throw new Error('Only an administrator can release a maintenance/out-of-service bed.');
    if(!confirm(`Change bed status to ${b.dataset.status}?`))break;
    await runAction(()=>api(`/api/admin/beds/${id}/status`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status,reason:'Administrator restored bed after maintenance'})}),'Bed status updated.');break;
   case 'cancel-admission-request':{const reason=prompt('Cancellation reason (required). The request will be retained in history, not physically deleted:');if(!reason||!reason.trim())break;if(!confirm('Cancel this unallocated admission request?'))break;await runAction(()=>api(`/api/receptionist/requests/${id}/cancel`,{method:'POST',body:JSON.stringify({reason:reason.trim()})}),'Admission request cancelled; history retained.');break;}
   case 'admin-cancel-admission-request':{const reason=prompt('Admin cancellation reason (required). The request will be retained in history:');if(!reason||!reason.trim())break;if(!confirm('Cancel this unallocated admission request?'))break;await runAction(()=>api(`/api/admin/admission-requests/${id}/cancel`,{method:'POST',body:JSON.stringify({reason:reason.trim()})}),'Admission request cancelled; history retained.');break;}
   case 'refresh-page':renderPage();break;case 'refresh-patients':renderPage();break;
   case 'filter-audit':{const q=new URLSearchParams();if($('#audit-action')?.value)q.set('action',$('#audit-action').value);if($('#audit-user')?.value)q.set('user',$('#audit-user').value);const rows=await api('/api/admin/audit?'+q);$('#audit-table').innerHTML=auditTable(rows);break;}
   case 'download-occupancy':await api('/api/admin/reports/occupancy.csv');break;case 'billing-csv':await api('/api/receptionist/billing/invoices.csv');break;case 'print':window.print();break;
   case 'verify-request':{const esi=prompt('Confirm clinical ESI level (1 = most urgent, 5 = least urgent):','5');if(!esi)return;const clinicalIsolationVerified=confirm('Has a qualified clinician verified the isolation requirement?');await runAction(()=>api(`/api/receptionist/requests/${id}/verify`,{method:'POST',body:JSON.stringify({esiLevel:Number(esi),clinicalIsolationVerified})}),'Request verified.');break;}
   case 'allocate':await allocateRequest(id);break;case 'waitlist':await runAction(()=>api(`/api/receptionist/requests/${id}/waitlist`,{method:'POST'}),'Added to waiting list.');break;
   case 'transfer':await transfer(id);break;case 'discharge':await discharge(id);break;
   case 'razorpay-pay':await startRazorpayPayment(id,false);break;case 'patient-pay-online':closeModal();await startRazorpayPayment(id,true);break;
   case 'payment':{const balance=Number(b.dataset.balance);const amount=prompt(`Outstanding balance: ${money(balance)}\nPayment amount:`);if(amount===null)return;const paymentMethod=prompt('Payment method: CASH, UPI, CARD, BANK_TRANSFER, INSURANCE or OTHER','CASH');if(!paymentMethod)return;await runAction(()=>api(`/api/receptionist/billing/invoices/${id}/payments`,{method:'POST',body:JSON.stringify({amount:Number(amount),paymentMethod})}),'Payment recorded.');break;}
   case 'patient-bill':await patientBill(id);break;
  }
 }catch(err){toast(err.message,'error');}
});
document.addEventListener('submit',async e=>{
 if(e.target.id==='patient-form'){
  e.preventDefault();const form=e.target;const data=formObject(form);
  if(data.password!==data.confirmPassword){toast('Password and confirm password do not match.','error');return;}
  try{const result=await api('/api/receptionist/patients',{method:'POST',body:JSON.stringify(data)});await renderPage();openModal('Patient registered · Login credentials',`<p>Patient record and patient portal account have both been created.</p><div class="panel"><p>Patient: <b>${esc(data.fullName)}</b></p><p>UHID: <b>${esc(result.uhid)}</b></p><p>Patient User ID / Login ID: <b>${esc(result.loginId)}</b></p><p>Username: <b>${esc(result.username)}</b></p><p>Initial password: <b>${esc(data.password)}</b></p></div><p class="muted">Give these details to the patient. Password is stored as a BCrypt hash; it is not saved in plain text.</p>`);}
  catch(err){toast(err.message,'error');}
 }
 if(e.target.id==='admission-request-form'){e.preventDefault();await runAction(()=>api('/api/patient/admission-requests',{method:'POST',body:JSON.stringify(formObject(e.target))}),'Admission request submitted.');}
 if(e.target.id==='settings-form'){e.preventDefault();await runAction(()=>api('/api/admin/settings',{method:'PUT',body:JSON.stringify(formObject(e.target))}),'Settings updated.');}
});
document.addEventListener('input',e=>{
 if(e.target.id==='bed-search'||e.target.id==='bed-filter'){const rows=state.cache.beds||[];const term=($('#bed-search')?.value||'').toLowerCase();const status=$('#bed-filter')?.value||'';const filtered=rows.filter(x=>(!status||x.status===status)&&(`${x.bed_code} ${x.ward_name}`).toLowerCase().includes(term));const target=$('#bed-table');if(target)target.innerHTML=bedTable(filtered);}
 if(e.target.id==='reception-patient-search'){clearTimeout(window.__receptionPatientSearchTimer);window.__receptionPatientSearchTimer=setTimeout(async()=>{try{const rows=await api('/api/receptionist/patients?q='+encodeURIComponent(e.target.value));if($('#reception-patient-table'))$('#reception-patient-table').innerHTML=table(rows,[{key:'uhid',label:'UHID'},{key:'full_name',label:'Patient'},{key:'age',label:'Age'},{key:'gender',label:'Gender'},{key:'phone',label:'Phone'},{key:'insurance_type',label:'Payment type'},{key:'record_status',label:'Status',render:r=>statusTag(r.record_status)}],r=>`<button class="btn small" data-action="view-reception-patient" data-id="${r.patient_id}">View / Admit</button>`);}catch(err){toast(err.message,'error');}},250);}
 if(e.target.id==='patient-search'){clearTimeout(window.__patientSearchTimer);window.__patientSearchTimer=setTimeout(async()=>{try{const rows=await api('/api/admin/patients?q='+encodeURIComponent(e.target.value));if($('#patient-table'))$('#patient-table').innerHTML=patientTable(rows);}catch(err){toast(err.message,'error');}},250);}
});
async function init(){
 const saved=localStorage.getItem('ihbas_user');try{if(state.token&&saved){state.user=JSON.parse(saved);const me=await api('/api/auth/me');state.user=me;localStorage.setItem('ihbas_user',JSON.stringify(me));state.page='overview';renderShell();return;}}catch(_){}
 showLogin();
}
init();
